`are_equivalent(a, b)` decides whether two attribute strings refer to the same identity. The dedup
pipeline (app/dedup.py) calls it with a STABLE signature: are_equivalent(a, b) -> bool.
"""

import unicodedata


class IdentityCompare:
    def are_equivalent(self, a, b):
        # IDD-4408: canonicalize before comparing so canonically-equivalent but differently-composed
        # inputs (e.g. NFC vs NFD forms of the same accented name) match instead of producing duplicate
        # identities for the same entity. Genuinely different strings still compare as not equivalent.
        return unicodedata.normalize("NFC", a) == unicodedata.normalize("NFC", b)

